import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;

public class Solution {
    public int findLargestSubstring(List<String> strings) {
        int max = 0;
        Collections.sort(strings, new Comparator<String>() {
            @Override
            public int compare(String s1, String s2) {
                if (s1.length() != s2.length()) {
                    return s2.length() - s1.length();
                }
                return s1.compareTo(s2);
            }
        });

        String reversedString = "";
        int reversedLength = 0;
        for (int i = strings.size() - 1; i >= 0; i--) {
            String str = strings.get(i);
            reversedString = rev(str);
            reversedLength = str.length();

            // Check if either str or its inverse is a substring of any other string
            for (int j = 0; j < strings.size(); j++) {
                if (i != j) {
                    String otherStr = strings.get(j);
                    if (otherStr.contains(str) || otherStr.contains(str.substring(0,-1)) || otherStr.contains(str.substring(-1,0)) || otherStr.contains(str.substring(-2,0)) || otherStr.contains(str.substring(-3,0)) || otherStr.contains(str.substring(-4,0)) || otherStr.contains(str.substring(-5,0))) {
                        max = Math.max(max, reversedLength);
                    }
                }
            }
        }
        return max;
    }

    private String rev(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            sb.append(s.charAt(i));
        }
        return sb.toString();
    }

