private static boolean isOilNearby(int x, int y, char[][] grid) {
        return isValidPosition(x, y, grid) && (grid[x][y] == '*' 
                || isOilNearby(x - 1, y, grid) 
                || isOilNearby(x + 1, y, grid) 
                || isOilNearby(x, y - 1, grid) 
                || isOilNearby(x, y + 1, grid));
    }

