public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int count = 0;
    boolean[][] visited = new boolean[grid.length][grid[0].length];

    for (int i = 0; i < grid.length; i++) {
        for (int j = 0; j < grid[0].length; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                DFS(grid, visited, i, j);
            }
        }
    }

    return count;
}

private static void DFS(char[][] grid, boolean[][] visited, int x, int y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || visited[x][y] || grid[x][y] != '*') {
        return;
    }

    visited[x][y] = true;
    DFS(grid, visited, x + 1, y); // Down
    DFS(grid, visited, x - 1, y); // Up
    DFS(grid, visited, x, y + 1); // Right
    DFS(grid, visited, x, y - 1); // Left
}

public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int rows = grid.length;
    if (rows == 0) return count;

    int cols = grid[0].length;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                // Use DFS to mark connected oil deposits
                dfsMarked(i, j, grid);
            }
        }
    }
    return count;
}

private static void dfsMarked(int x, int y, char[][] grid) {
    int rows = grid.length;
    int cols = grid[0].length;

    // Check boundaries and validity
    if (x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] != '@') {
        return;
    }

    // Mark the current cell as visited
    grid[x][y] = '*';

    // Recur for all eight possible directions
    dfsMarked(x + 1, y, grid); // Down
    dfsMarked(x - 1, y, grid); // Up
    dfsMarked(x, y + 1, grid); // Right
    dfsMarked(x, y - 1, grid); // Left
    dfsMarked(x + 1, y + 1, grid); // Down-Right
    dfsMarked(x - 1, y - 1, grid); // Up-Left
    dfsMarked(x + 1, y - 1, grid); // Down-Left
    dfsMarked(x - 1, y + 1, grid); // Up-Right
}

