private static boolean isValidOilDeposit(char[][] grid, int x, int y) {
    // Define the directions for checking the four surrounding cells
    int[][] directions = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    boolean isValid = true;

    for (int[] dir : directions) {
        int newX = x + dir[0];
        int newY = y + dir[1];
        // Check if the new position is within the grid bounds
        if (newX >= 0 && newX < grid.length && newY >= 0 && newY < grid[newX].length) {
            // Check if the adjacent cell contains oil
            if (grid[newX][newY] == '@') {
                return false;
            }
        }
    }

    return isValid;
}

