    return canTravelMazeRecursive(n, start, end, paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeRecursive(int n, int[] current, int[] end, int[][] paths, Set<Integer> visited) {
    if (visited.contains(current[0]) || current[0] < 1 || current[0] > n || current[1] < 1 || current[1] > n) {
        return false;
    }
    visited.add(current[0]);
    if (Arrays.equals(current, end)) {
        return true;
    }
    for (int i = 0; i < paths.length; i++) {
        if (paths[i][0] == current[0] && paths[i][1] == current[1] + paths[i][2]) {
            if (canTravelMazeRecursive(n, new int[]{current[0], current[1] + paths[i][2]}, end, paths, visited)) {
                return true;
            }
        }
        if (paths[i][1] == current[0] && paths[i][0] == current[1] - paths[i][2]) {
            if (canTravelMazeRecursive(n, new int[]{current[0], current[1] - paths[i][2]}, end, paths, visited)) {
                return true;
            }
        }
    }
    visited.remove(current[0]);
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
