        int x2 = path[2] - 1;
        int y2 = path[3] - 1;
        graph[x1][y1] = true;
        graph[x2][y2] = true;
    }

    boolean result = isPathExists(graph, start[0] - 1, start[1] - 1, end[0] - 1, end[1] - 1);
    return result ? "can be travelled" : "cannot be travelled";
}

private static boolean isPathExists(boolean[][] graph, int x1, int y1, int x2, int y2) {
