public static String appx(String word1, String word2) {
    int intersection = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                intersection++;
                break;
            }
        }
    }
    int numerator = intersection;
    int denominator = word1.length() + word2.length() - intersection;
    int gcd = gcd(numerator, denominator);
    return "appx(" + word1 + ", " + word2 + ") = " + (numerator / gcd) + "/" + (denominator / gcd);
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    int denominator = word1.length() + word2.length() - commonLetters;
    if (denominator == 0) {
        return "The denominator is zero, cannot calculate the fraction.";
    }

    int num = commonLetters;
    int GCD = gcd(num, denominator);
    num /= GCD;
    denominator /= GCD;

    return "appx(" + word1 + ", " + word2 + ") = " + num + "/" + denominator;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

public static String appx(String word1, String word2) {
    int commonLetters = 0;
    int length1 = word1.length();
    int length2 = word2.length();

    for (int i = 0; i < length1 && i < length2; i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }

    if (commonLetters == 0) {
        return "0";
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + (2 * commonLetters) + "/" + (length1 + length2);
    }
}

