public double trimMean(int[] arr) {
	List<Integer> integers = Arrays.stream(arr).boxed().collect(Collectors.toList());
	Collections.sort(integers);
	double mean = 0.0;
	for (int i = integers.size() / 20; i < integers.size() * 19 / 20; i++) {
		mean += integers.get(i);
	}
	return mean / 9.0;
}

