        if ((num % k) % 2 != 0) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] mp = new int[k];
    int n = arr.length;
    for (int a : arr) {
        mp[(a % k + k) % k]++;
    }

    int i = 1;
    int j = k - 1;
    while (i <= j) {
        if (k % 2 == 1 && mp[i] != mp[j]) {
            return false;
        } else if (mp[i] % 2 == 1) {
            i++;
            j--;
        } else {
            i++;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    int[] remainderFrequency = new int[k];
    for (int num : arr) {
        int remainder = num % k;
        remainderFrequency[remainder]++;
    }

    for (int i = 1; i < k / 2; i++) {
        if (remainderFrequency[i] != remainderFrequency[k - i]) {
            return false;
        }
    }
    return remainderFrequency[k / 2] % 2 == 0;
}

public boolean canArrange(int[] arr, int k) {
    // Count the occurrences of each element modulo k
    int[] mods = new int[k];
    for (int num : arr) {
        mods[num % k]++;
    }

    // Check if the possible combinations of elements in pairs divide by k
    for (int i = 0; i < k / 2; i++) {
        if ((i != k - i && mods[i] != mods[k - i]) || (i == k - i && mods[i] == arr.length / 2)) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
        if (arr == null || arr.length % 2 != 0) {
            return false;
        }
        Map<Integer, Integer> modCount = new HashMap<>();
        List<Integer> nonZeroMod = new ArrayList<>();
        for (int num : arr) {
            int mod = num % k;
            modCount.put(mod, modCount.getOrDefault(mod, 0) + 1);
        }
        nonZeroMod.addAll(modCount.keySet());
        nonZeroMod.sort(Comparator.naturalOrder());
        int i = 0;
        int j = nonZeroMod.size() - 1;
        while (i < j) {
            if (nonZeroMod.get(i) + nonZeroMod.get(j) != k) {
                return false;
            }
            i++;
            j--;
        }
        for (int count : modCount.values()) {
            if (count % 2 != 0) {
                return false;
            }
        }
        int totalEvenMod = modCount.values().stream().filter(count -> count % 2 == 0).count();
        if (totalEvenMod < arr.length / 2) {
            return false;
        }
        return true;
    }

