public int dfs(int index, int[] visited, int[] timeStamps) {
        if (visited[index] == 2) return 0;

        visited[index] = 1;

        int totalTime = 0;

        for (int i = 0; i < graph.n; i++) {
            if (graph.adj[index][i] == 1) {
                if (dfs(i, visited, timeStamps) > 0) totalTime += 2;
                else if (hasApple[i]) totalTime += 2;
            }
        }

        visited[index] = 2;
        return totalTime;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Graph graph = new Graph(n);

        for (int[] edge : edges) {
            graph.addEdge(edge[0], edge[1]);
        }

        boolean[] visited = new boolean[n];
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{0, 0});

        int totalTime = 0;
        while (!queue.isEmpty()) {
            int[] node = queue.poll();
            int time = node[1];

            if (time == 2 /* already visited */) {
                continue;
            }

            totalTime += time;
            visited[node[0]] = true;

            for (int neighbor : graph.adj[node[0]]) {
                if ((totalTime > 0 || hasApple[neighbor]) && !visited[neighbor]) {
                    queue.offer(new int[]{neighbor, time + 1});
                }
            }
        }

        return totalTime;
    }

