        return helper(adjacencyList, hasApple, 0, -1);
    }

private int helper(HashMap<Integer, List<Integer>> adjacencyList, boolean[] hasApple, int currentNode, int parent) {
        int totalTime = 0;
        if (parent != -1 && hasApple[parent]) {
            totalTime += 2; // Time to go back and return
        }

        int additionalTime = 0;
        for (int neighbor : adjacencyList.getOrDefault(currentNode, Collections.emptyList())) {
            if (neighbor != parent) {
                additionalTime += helper(adjacencyList, hasApple, neighbor, currentNode);
            }
        }

        return additionalTime + totalTime;
    }

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        helper(0, hasApple);
        return time;
    }

public void helper(int index, boolean[] hasApple) {
        time++;
        apple = hasApple[index];
        List<Integer> children = graph.get(index);
        for (int child : children) {
            if (!apple && !helper(child, hasApple)) continue;
            time++;
        }
    }

public String sortString(String s) {
    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    int n = chars.length;
    StringBuilder sorted = new StringBuilder();

    while (n > 0) {
        for (int i = 0; i < n / 2; i++) {
            sorted.append(chars[i]);
        }
        for (int i = n - 1; i >= n / 2; i--) {
            sorted.append(chars[i]);
        }
        n = n / 2;
    }

    return sorted.toString();
}

public String sortString(String s) {
    int[] map = new int[26];
    int n = s.length();
    int i = 0;

    // Count the occurrences of each character
    while (i < n) {
        char ch = s.charAt(i);
        map[ch - 'a']++;
        i++;
    }

    StringBuilder sb = new StringBuilder();
    // Alternate between smallest and largest characters
    for (char ch = 'a'; ch <= 'z'; ch++) {
        while (map[ch - 'a'] > 0) {
            sb.append(ch);
            map[ch - 'a']--;
        }
    }

    for (char ch = 'z'; ch >= 'a'; ch--) {
        while (map[ch - 'a'] > 0) {
            sb.append(ch);
            map[ch - 'a']--;
        }
    }

    return sb.toString();
}

public String sortString(String s) {
        StringBuilder result = new StringBuilder();
        int[] countMap = new int[26]; // Array to count occurrences of each character

        // Count occurrences of each character in the string
        for (char c : s.toCharArray()) {
            countMap[c - 'a']++;
        }

        for (int i = 0; i < s.length(); i++) {
            // Pick the smallest character that hasn't been used yet
            char minChar = 'a';
            for (int j = 0; j < 26; j++) {
                if (countMap[j] > 0 && minChar > 'a' + j) {
                    minChar = 'a' + j;
                }
            }
            result.append(minChar);
            countMap[minChar - 'a']--;

            // Pick the largest character that hasn't been used yet
            char maxChar = 'a';
            for (int j = 25; j >= 0; j--) {
                if (countMap[j] > 0 && maxChar < 'a' + j) {
                    maxChar = 'a' + j;
                }
            }
            result.append(maxChar);
            countMap[maxChar - 'a']--;
        }

        return result.toString();
    }

public String sortString(String s) {
    if (s == null || s.isEmpty()) return s;

    int[] charCount = new int[26]; // Array to count occurrences of each character
    for (char c : s.toCharArray()) charCount[c - 'a']++;

    StringBuilder result = new StringBuilder();
    while (result.length() < s.length()) {
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0) {
                result.append((char) ('a' + i));
                charCount[i]--;
            }
        }        
        for (int i = 25; i >= 0; i--) {
            if (charCount[i] > 0) {
                result.append((char) ('a' + i));
                charCount[i]--;
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    StringBuilder sortedString = new StringBuilder();
    int[] charCount = new int['z' - 'a' + 1];
    for (char c : s.toCharArray()) {
        charCount[c - 'a']++;
    }

    boolean isAscending = true;

    while (sortedString.length() < s.length()) {
        Character minChar = null;
        int minCount = Integer.MAX_VALUE;
        Character maxChar = null;
        int maxCount = Integer.MIN_VALUE;

        if (isAscending) {
            for (char c = 'a'; c <= 'z'; c++) {
                if (charCount[c - 'a'] > 0 && charCount[c - 'a'] < minCount) {
                    minChar = c;
                    minCount = charCount[c - 'a'];
                }
            }
        } else {
            for (char c = 'z'; c >= 'a'; c--) {
                if (charCount[c - 'a'] > 0 && charCount[c - 'a'] < maxCount) {
                    maxChar = c;
                    maxCount = charCount[c - 'a'];
                }
            }
        }

        if (minChar == null) {
            isAscending = !isAscending;
            break;
        }

        sortedString.append(minChar);
        charCount[minChar - 'a']--;

        if (maxChar == null) {
            isAscending = !isAscending;
            break;
        }

        sortedString.append(maxChar);
        charCount[maxChar - 'a']--;

        if (charCount[minChar - 'a'] == 0) {
            isAscending = !isAscending;
        }

        if (charCount[maxChar - 'a'] == 0) {
            isAscending = !isAscending;
        }
    }

    return sortedString.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int totalSum = 0;

    // Calculate the total sum of the array
    for (int num : nums) {
        totalSum += num;
    }

    // If the total sum is odd, it's impossible to split the array with the same average
    if (totalSum % n != 0) {
        return false;
    }

    // Find the average of each subarray
    int targetAverage = totalSum / n;
    boolean[] dp = new boolean[n];

    // Check if we can get the target average with any subarray
    for (int i = 0; i < n; i++) {
        dp[i] = dp[i - 1] || (i > 0 && nums[i - 1] == targetAverage);
    }

    // Check if we can get the target average starting from the first element
    for (int i = 1; i < n; i++) {
        if (dp[i - 1]) {
            if (nums[i] == targetAverage * (n - 1)) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int total = Arrays.stream(nums).sum();
    double avg = total / nums.length;
    if (avg <= 0 || total % nums.length != 0) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
        if (sum >= avg * (nums.length - 1)) {
            double remainingSum = total - sum;
            return remainingSum == avg * (nums.length - 1);
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length == 0 || nums.length == 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    if (sum % 2 != 0) {
        return false;
    }
    int average = sum / 2;

    int totalSum = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        int leftSum = totalSum + nums[i];
        if (leftSum == average) {
            return true;
        }
        for (int j = i + 1; j < nums.length; j++) {
            int rightSum = totalSum + nums[j];
            if (rightSum == average) {
                return true;
            }
        }
        totalSum += nums[i];
    }
    return false;
}

