}

public boolean splitArraySameAverage(int[] nums) {
        int totalSum = Arrays.stream(nums).sum();
        if (totalSum % 2 != 0) return false;
        int target = totalSum / 2;
        return canPartition(nums, target);
    }

private boolean canPartition(int[] nums, int target) {
        if (target <= 0) return false;
        int n = nums.length;
        boolean[][] dp = new boolean[n + 1][target + 1];
        dp[0][0] = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= target; j++) {
                if (nums[i - 1] <= j) {
                    dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
                }
            }
        }
        return dp[n][target];
    }

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return Math.min(cost[0], 0);
    }

    int [] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i-1] + cost[i], dp[i-2] + cost[i]);
    }

    return dp[n-1];
}

public int minCostClimbingStairs(int[] cost) {
        // Initialize a map to store the minimum cost to reach each step
        Map<Integer, Integer> minCostMap = new HashMap<>();
        minCostMap.put(0, 0);
        minCostMap.put(1, 0);

        // Iterate through the array, calculating the minimum cost to reach each step
        for (int i = 2; i <= cost.length; i++) {
            minCostMap.put(i, Math.min(minCostMap.get(i - 1) + cost[i - 1], minCostMap.get(i - 2) + cost[i - 2]));
        }

        // Return the minimum cost to reach the top of the floor
        return minCostMap.get(cost.length);
    }

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);

    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < n; i++) {
        dp[i] = cost[i] + Math.min(dp[i-1], dp[i-2]);
    }

    return Math.min(dp[n-1], dp[n-2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int oneStep = cost[0];
    int twoSteps = cost[1];
    int minCost = cost[0] < cost[1] ? cost[0] : cost[1];

    for (int i = 2; i < cost.length; i++) {
        int temp = oneStep;
        oneStep = cost[i] + Math.min(oneStep, twoSteps);
        twoSteps = temp;
        minCost = Math.min(minCost, Math.min(oneStep, twoSteps));
    }

    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("Cost array must not be null or empty");
    }
    if (cost.length == 1) {
        return cost[0];
    }
    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < cost.length; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return dp[cost.length - 1];
}

