public boolean hasAllCodes(String s, int k) {
    int required = (int) Math.pow(2, k);
    boolean[] exists = new boolean[required];
    int mask = 0;

    for (int i = 0; i < s.length(); i++) {
        mask <<= 1;
        if (s.charAt(i) == '1') mask |= 1;
        if (i >= k - 1) {
            exists[mask] = true;
            mask >>= 1;
        }
    }

    for (boolean b : exists) {
        if (!b) return false;
    }
    return true;
}

public boolean hasAllCodes(String s, int k) {
    int maxNumber = (1 << k) - 1; // Calculates the maximum value for k bits
    int[] occurrences = new int[maxNumber + 1]; // Tracks occurrences of each binary string of length k

    // Iterate through the substring of length k and update the occurrence count
    for (int i = 0; i <= s.length() - k; i++) {
        int number = Integer.parseInt(s.substring(i, i + k), 2);
        occurrences[number]++;
    }

    // Check if all possible binary strings of length k have at least one occurrence
    return Arrays.stream(occurrences).allMatch(count -> count > 0);
}

public boolean hasAllCodes(String s, int k) {
        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            String substring = s.substring(i, i + k);
            if (seen.contains(substring)) {
                return false;
            }
            seen.add(substring);
        }
        return seen.size() == Math.pow(2, k);
    }

public boolean hasAllCodes(String s, int k) {
    int n = s.length(), res = 1 << k, total = 1 << k;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
        dp[i + 1] = (dp[i] + (s.charAt(i) == '1' ? 1 : 0)) % total;
    }
    for (int i = 1; i <= k; i++) {
        // Check if all combinations of length i have appeared in string s
        if (dp[n] < (1 << k)) return false;
    }
    return true;
}

