public int minOperations(int n) {
    int sum = n;
    int totalOperations = 0;

    for (int i = 1; i < n; i += 2) {
        totalOperations += sum - i;
        sum -= i;
    }

    return totalOperations;
}

public int minOperations(int n) {
    int operations = 0;
    for (int i = 0; i < n / 2; i++) {
        int diff = (2 * (n / 2 + i)) - (2 * (i + 1)) + 1;
        operations += diff;
    }
    return operations;
}

public int minOperations(int n) {
    int count = 0;
    int target = 1 + (n - 1) * 2;

    for (int i = 1; i * 2 < n; i++) {
        count += Math.abs(target - (i * 2));
    }

    return count;
}

