public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    int maxSum = 0;
    int minSum = 0;
    int currentMax = 0;
    int currentMin = 0;

    for(int num: nums){
        currentMax = Math.max(num, currentMax + num);
        currentMin = Math.min(num, currentMin + num);

        maxSum = Math.max(maxSum, currentMax);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
    int n = nums.length;
    int maxSubsumIncludingCurrent = nums[0];
    int maxSubsumNotIncludingCurrent = 0;
    int result = Math.abs(nums[0]);

    for (int i = 1; i < n; i++) {
        maxSubsumIncludingCurrent = Math.max(nums[i], maxSubsumIncludingCurrent + nums[i]);
        maxSubsumNotIncludingCurrent = Math.max(maxSubsumNotIncludingCurrent + nums[i], nums[i]);
        result = Math.max(result, Math.max(maxSubsumIncludingCurrent, -maxSubsumNotIncludingCurrent));
    }

    return result;
}

