        maxSum = Math.max(nums[i], maxSum + nums[i]);
        minSum = Math.min(nums[i], minSum + nums[i]);
        maxSum = Math.max(maxSum, 0);
        minSum = Math.min(minSum, 0);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;

    for (int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);
    }

    return Math.max(maxSum, -minSum);
}

public int findMinFibonacciNumbers(int k) {
    int fibSeq[] = new int[30];
    fibSeq[1] = 1;
    fibSeq[2] = 1;

    for (int i = 3; i <= 29; i++) {
        fibSeq[i] = fibSeq[i - 1] + fibSeq[i - 2];
    }

    PriorityQueue<Integer> pq = new PriorityQueue<>();
    for (int i = 29; i >= 2; i--) {
        if (fibSeq[i] <= k) {
            pq.offer(fibSeq[i]);
        }
    }

    int count = 0;
    while (!pq.isEmpty() && k > 0) {
        if (k >= pq.peek()) {
            k -= pq.poll();
            count++;
        } else {
            break;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fib = new ArrayList<>();
    fib.add(0);
    fib.add(1);
    int i = 2;
    while (fib.get(i - 1) < k) {
        fib.add(fib.get(i - 1) + fib.get(i - 2));
        i++;
    }

    int count = 0;
    for (int maximizing = fib.size() - 1; maximizing > 0 && k > 0; maximizing--) {
        int remainder = k % fib.get(maximizing);
        if (remainder == 0) {
            count += fib.get(maximizing);
            return count;
        }
        k = remainder;
        count++;
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
    List<Integer> fibS = new ArrayList<>();
    fibS.add(1);
    fibS.add(1);
    while (fibS.get(fibS.size() - 1) + fibS.get(fibS.size() - 2) <= k) {
        fibS.add(fibS.get(fibS.size() - 1) + fibS.get(fibS.size() - 2));
    }

    int c = k;
    int count = 0;
    for (int i = fibS.size() - 1; i >= 0 && c > 0; i--) {
        if (c >= fibS.get(i)) {
            c -= fibS.get(i);
            count++;
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    int n = 1;
    int m = 1;
    while (n + m <= k) {
        int temp = n + m;
        n = m;
        m = temp;
    }
    int[] arr = new int[(k + 1) / m];
    int j = 0;
    while (k > 0) {
        int temp = k / m;
        arr[j++] = m;
        k -= m * temp;
        m = n;
        n -= m * temp;
    }
    Arrays.sort(arr);
    return j;
}

public int findMinFibonacciNumbers(int k) {
        List<Integer> fibNumbers = new ArrayList<>();
        int sum = 0;
        int count = 0;

        // Generate Fibonacci numbers less than or equal to the given k
        while (sum <= k) {
            fibNumbers.add(sum);
            int nextFib = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
            if (nextFib > k) break;
            fibNumbers.add(nextFib);
            sum += nextFib;
        }

        // Sort the Fibonacci numbers in descending order
        Collections.sort(fibNumbers, Collections.reverseOrder());

        // Start adding Fibonacci numbers from the largest to the smallest
        for (int num : fibNumbers) {
            if (num <= k) {
                count++;
                k -= num;
            }
        }

        return count;
    }

public int kthFactor(int n, int k) {
        // Check if the kth factor exists in the range of factors of n
        if (k <= 1 || k > n) {
            return -1;
        }

        // Loop through the factors of n to find the kth factor
        int factorCount = 0;
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) {
                factorCount++;
                if (factorCount == k) {
                    return i;
                }
            }
        }

        return -1; // Return -1 if the kth factor does not exist
    }

public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }
    return -1;
}

public int kthFactor(int n, int k) {
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            if (--k == 0) return i;
            if (i != n / i && --k == 0) return n / i;
        }
    }
    return -1;
}

public static int kthFactor(int n, int k) {
