public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            if (i == n / i) {
                k--;
            } else {
                count += 2;
                k -= 2;
            }
        }
        if (k == 0) {
            return i;
        }
    }
    return -1;
}

