        }
    }

    for (char c : stack) {
        result.append(c);
    }

    return result.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    Set<String> seen = new HashSet<>();
    int maxUnique = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j <= n; j++) {
            String substring = s.substring(i, j);
            if (!seen.contains(substring)) {
                seen.add(substring);
                maxUnique++;
            } else {
                // reached a known substring, cannot split further
                break;
            }
        }
    }

    return maxUnique;
}

public int maxUniqueSplit(String s) {
        Set<String> seen = new HashSet<>();
        char[] chars = s.toCharArray();
        int max = 0;

        for (int i = 0; i < chars.length; i++) {
            StringBuilder current = new StringBuilder();
            for (int j = i; j < chars.length; j++) {
                current.append(chars[j]);
                if (!seen.contains(current.toString())) {
                    seen.add(current.toString());
                    max++;
                } else {
                    break;
                }
            }
        }

        return max;
    }

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }

    int maxUnique = 0;
    int start = 0;
    HashSet<String> uniqueSubs = new HashSet<>();

    while (start < s.length()) {
        while (start < s.length() && !uniqueSubs.add(s.substring(start))) {
            start++;
        }
        maxUnique = Math.max(maxUnique, uniqueSubs.size());
        if (start >= s.length()) {
            break;
        }
        uniqueSubs.remove(s.substring(start - 1));
        start++;
    }

    return maxUnique;
}

public int maxUniqueSplit(String s) {
    int maxUnique = 0;
    int start = 0, end = 0;
    StringBuilder currentString = new StringBuilder();
    Set<Character> seenCharacters = new HashSet<>();

    while (end < s.length()) {
        char currentChar = s.charAt(end);
        if (seenCharacters.add(currentChar)) {
            currentString.append(currentChar);
            end++;
            maxUnique++;
        } else {
            seenCharacters.remove(s.charAt(start));
            currentString.deleteCharAt(currentString.length() - 1);
            start++;
        }
    }

    return maxUnique;
}

public int maxUniqueSplit(String s) {
    Set<String> used = new HashSet<>();
    maxUniqueSplit(s, "", "", used);
    return used.size();
}

private void maxUniqueSplit(String s, String prefix, String prevPrefix, Set<String> used) {
    if (s.isEmpty()) {
        return;
    }
    used.add(prefix);
    char ch = s.charAt(0);
    maxUniqueSplit(s.substring(1), prefix + ch, ch, used);
    if (!prevPrefix.isEmpty()) {
        maxUniqueSplit(s.substring(1), prefix, prevPrefix + "++", used);
    }
}

public int minOperations(String[] logs) {
    int level = 0;
    for (String log : logs) {
        if (log.equals("..")) {
            if (level > 0) {
                level--;
            }
        } else if (!log.isEmpty()) {
            level++;
        }
    }
    return level;
}

public int minOperations(String[] logs) {
    int currentPathDepth = 0;
    for (String log : logs) {
        if ("../".equals(log)) {
            if (currentPathDepth > 0) {
                currentPathDepth--;
            }
        } else {
            currentPathDepth++;
        }
    }
    return currentPathDepth;
}

public int minOperations(String[] logs) {
    int count = 0;
    for (String log : logs) {
        if (log.equals("..")) {
            if (count > 0) {
                count--;
            }
        } else if (!log.equals(".")) {
            count++;
        }
    }
    return count;
}

public int minOperations(String[] logs) {
    int pathDepth = 0;

    for (String log : logs) {
        if (log.equals("")) {
            // No change
        } else if (log.equals("../")) {
            // Go back, decrement depth
            if (pathDepth > 0) {
                pathDepth--;
            }
        } else {
            // Go forward, increment depth
            pathDepth++;
        }
    }

    return pathDepth;
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }

    Stack<String> stack = new Stack<>();

    for (String log : logs) {
        if (log.equals("../")) {
            if (!stack.isEmpty()) {
                stack.pop();
            }
        } else if (!"".equals(log)) {
            stack.push(log);
        }
    }

    return stack.size();
}

public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = n - 1; i >= 0; i--) {
        int remainder = k % 26;
        if (remainder == 0) {
            result[i] = 'z';
            k -= 25;
        } else {
            result[i] = (char) ('a' + remainder - 1);
            k -= remainder;
        }
    }
    return String.valueOf(result);
}

public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();

    while (k > 0) {
        if (n == 1) {
            result.insert(0, (char) (k + 96));
            k = 0;
        } else {
            result.insert(0, 'z');
            k -= 26;
            n--;
        }
    }

    return result.toString();
}

public String getSmallestString(int n, int k) {
    StringBuilder smallestString = new StringBuilder();

    for (int i = 1; i <= n; i++) {
        smallestString.append((char) ('a' + (k % 26 - 1)));
        k -= (k % 26 - 1);
        k /= 26;
    }

    return smallestString.toString();
}

public String getSmallestString(int n, int k) {
        String s = "";
        int j = n - 1;
        for (int i = 1; i <= 26; i++) {
            if (k >= i) {
                s += (char) ('a' + i - 1);
                k -= i;
            } else {
                if (s.length() == n) {
                    break;
                }
                s += (char) ('z' - k + 1);
