public static double calculateProbability(int n) {
    if (n <= 0) {
        return 0;
    }
    if (n == 1) {
        return 1.0;
    } else if (n == 2) {
        return 0.5;
    }
    double dp[] = new double[n + 1];
    dp[1] = 0;
    dp[2] = 1;
    for (int i = 3; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2];
    }
    return dp[n];
}

public static double calculateProbability(int n) {
    if (n <= 2) {
        return 1.0; // Only one or two passengers can sit in their own seat.
    }
    return 0.4;
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0;
    }
    double result = 0.5;
    for (int i = 3; i <= n; i++) {
        result *= (2.0 * (i - 1) / i);
    }
    return result;
}

public static double calculateProbability(int n) {
    if (n <= 1) {
        return 1.0;
    }
    double[][] dp = new double[n + 1][n + 1];
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= i; j++) {
            dp[i][j] = j == 0 ? 1.0 : j == i ? 1.0 - dp[i - 1][i - 1] : dp[i - 1][j - 1] + dp[i - 1][j] / (2 * i - 1);
        }
    }
    return dp[n][n] / (2 * n - 1);
}

public static int singleNumber(int[] nums) {
    int ones = 0;
    int twos = 0;
    for (int num : nums) {
        ones = (~twos & ones) & num;
        twos = (~ones & twos) & num;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    int one = 0;
    int two = 0;
    int three = 0;
    for (int num : nums) {
        one ^= num & ~two;
        two ^= num & ~one;
        three ^= num & ~one & ~two;
    }
    return one;
}

public static int singleNumber(int[] nums) {
    int a = 0, b = 0;
    for (int num : nums) {
        b = (b ^ num) & ~a;
        a = (a ^ num) & ~b;
    }
    return a;
}

public static int singleNumber(int[] nums) {
    int low = 0;
    int high = 31;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        boolean bitCount = checkBit(nums, mid);
        if (bitCount == 0) {
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

private static boolean checkBit(int[] nums, int index) {
 int count = 0;
 for (int num : nums) {
     if ((num & (1 << index)) != 0) {
         count++;
     }
 }
 return count % 3 == 1;
}

public static int singleNumber(final int[] nums) {
    int seen once = 0, seen Twice = 0;
    for (final int num : nums) {
        seenTwice |= seenOnce & num;
        seenOnce ^= num;
        seenOnce &= ~seenTwice;
    }
    return seenOnce;
}

