public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> steppingNumbers = new ArrayList<>();
    bfs(0, steppingNumbers, low, high);
    return steppingNumbers;
}

private static void bfs(int num, List<Integer> result, int low, int high) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(num);

    while (!queue.isEmpty()) {
        num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }

        int nextDigit = num * 10 + num / 10 + 1;
        if (nextDigit <= high && nextDigit - low >= 0) {
            queue.offer(nextDigit);
        }

        nextDigit = num * 10 + num / 10 - 1;
        if (nextDigit <= high && nextDigit - low >= 0) {
            queue.offer(nextDigit);
        }
    }
}

