private static boolean isSteppingNumber(int num) {
    String numStr = String.valueOf(num);
    int length = numStr.length();

    for (int i = 1; i < length; i++) {
        int diff = Math.abs(numStr.charAt(i) - numStr.charAt(i - 1));
        if (diff != 1) {
            return false;
        }
    }

    return true;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
        if (low > high) return List.of();

        List<Integer> steppingNumbers = new ArrayList<>();
        int len = String.valueOf(high).length();
        int start = low;

        if (Integer.valueOf(String.valueOf(low)) < 10) {
            for (int i = 0; i < 10; i++) {
                steppingNumbers.add(i);
            }
            start = 10;
        }

        for (int num = start; num <= high; num++) {
            int curLen = String.valueOf(num).length();
            boolean isStepped = isStepping(num, len, curLen);

            if (isStepped && num >= low && num <= high) {
                steppingNumbers.add(num);
            }
        }

        steppingNumbers.sort(Integer::compare);
        return steppingNumbers;
    }

private static boolean isStepping(int num, int minLen, int curLen) {
        int prevDigit = num % 10;
        num /= 10;

        if (prevDigit > minLen && minLen == curLen) return false;

        for (; num != 0; num /= 10) {
            int nextDigit = num % 10;
            if (Math.abs(prevDigit - nextDigit) > 1) return false;
            prevDigit = nextDigit;
        }

        return true;
    }

public static List<Integer> findSteppingNumbers(int low, int high) {
    if (low == 0) {
        List<Integer> result = new ArrayList<>();
        result.add(0);
        return result;
    }

    List<Integer> result = new ArrayList<>();
    StringBuilder sb = new StringBuilder(String.valueOf(low));

    while (sb.length() <= high) {
        if (checkStepping(sb)) {
            result.add(Integer.parseInt(sb.toString()));
        }
        if (sb.charAt(sb.length() - 1) == '9') {
            break;
        }
        sb.append(sb.length() - 1 == 0 ? '0' : sb.charAt(sb.length() - 1) - 1);
        sb.append(sb.length() == 0 ? '0' : sb.charAt(sb.length() - 1) + 1);
    }

    return result;
}

private static boolean checkStepping(StringBuilder sb) {
    for (int i = 1; i < sb.length(); i++) {
        if (Math.abs(sb.charAt(i) - sb.charAt(i - 1)) != 1) {
            return false;
        }
    }
    return true;
}

public static int countDigitOne(int n) {
    int ones = 0;
    for (int i = 0; i <= n; i++) {
        int num = i;
        while (num > 0) {
            ones += num % 10 == 1 ? 1 : 0;
            num /= 10;
        }
    }
    return ones;
}

public static int countDigitOne(int n) {
    int digit = 1;
    int count = 0;
    int i = 1;

    while (i <= n) {
        int start = i * (int)Math.pow(10, digit - 1);
        int end = (i + 1) * (int)Math.pow(10, digit - 1) - 1;

        if (start == end) {
            if (n % digit == 1) {
                count++;
            }
            break;
        }

        int mode = n % (int)Math.pow(10, digit);
        int diff = end - start;

        if (mode == 0) {
            int countFromStart = start / digit;
            int countFromEnd = diff - countFromStart + 1;
        } else {
            int countFromStart = start / digit + 1;
            if (mode >= digit) {
                countFromEnd = diff - countFromStart + 1;
            } else {
                int countFromEnd = diff - countFromStart + 1;
            }
        }

        count += countFromStart * digit + countFromEnd;

        i++;
        digit++;
    }

    return count;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (int i = 0; i <= n; i++) {
        while (i > 0) {
            if (i % 10 == 1) {
                count++;
            }
            i /= 10;
        }
    }
    return count;
}

public static int countDigitOne(int n) {
    if (n == 0) {
        return 0;
    }

    int onesCount = 0;
    int firstDigit = 1;

    while (n > 0) {
        int digit = n % 10;

        if (digit == 1) {
            onesCount += (n + 8) / 9 * firstDigit + (n % 9 + 1);
        } else if (digit == 0) {
            onesCount += (n + 8) / 9 * firstDigit;
        }

        firstDigit *= 10;
        n /= 10;
    }

    return onesCount;
}

public static int countDigitOne(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        count += countHelper(i, 1);
    }
    return count;
}

private static int countHelper(int number, int currentPowerOfTen) {
    if (number < currentPowerOfTen) {
        return 0;
    }
    int firstDigit = number / currentPowerOfTen;
    return firstDigit + (currentPowerOfTen == 1 ? number % currentPowerOfTen + 1 : 1) * countHelper(firstDigit, currentPowerOfTen * 10) + 
            countHelper(number % currentPowerOfTen, currentPowerOfTen);
}

public static boolean isPowerOfTwo(int n) {
    // A number is a power of two if it is greater than 0 and its binary representation has only one '1'
    return n > 0 && (n & (n - 1)) == 0;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    while (n > 1) {
        if (n % 2 != 0) {
            return false;
        }
        n /= 2;
    }
    return true;
}

