public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int n = mat.length;
    int m = mat[0].length;
    int[][] dp = new int[n][m];

    int longest = Math.max(
        DP(mat, n, m, 0, 0, 0, 1, dp),
        DP(mat, n, m, 0, 0, 0, 0, dp),
        DP(mat, n, m, 0, 0, 0, -1, dp),
        DP(mat, n, m, 0, 0, 0, -1, dp)
    );

    return longest;
}

private static int DP(int[][] mat, int n, int m, int r, int c, int dirX, int dirY, int[][] dp) {
    if (r < 0 || r >= n || c < 0 || c >= m || mat[r][c] == 0) {
        return 0;
    }
    int nextX = r + dirX;
    int nextY = c + dirY;
    if (dp[nextX][nextY] == 0) {
        dp[nextX][nextY] = 1 + DP(mat, n, m, nextX, nextY, dirX, dirY, dp);
    }
    return dp[nextX][nextY];
}

