public static int squarePermutations(int[] A) {
    int count = 0;
    backtrack(A, 0, count);
    return count;
}

private static void backtrack(int[] A, int i, int& count) {
    if (i == A.length - 1) {
        if (Math.sqrt(A[i - 1] + A[i]) == Math.round(Math.sqrt(A[i - 1] + A[i])))
            count++;
        return;
    }

    for (int j = i + 1; j < A.length; j++) {
        swap(A, i, j);
        backtrack(A, i + 1, count);
        swap(A, i, j); // Backtrack to restore the original array
    }
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 0;
    }

    Map<Integer, Integer> map = new HashMap<>();
    for (int num : A) {
        if (!map.containsKey(num)) {
            map.put(num, 1);
        } else {
            map.put(num, map.get(num) + 1);
        }
    }

    int count = 1;
    for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
        int value = entry.getValue();
        if (value % 2 != 0) {
            return 0;
        }
        count *= factorial(value / 2);
    }

    return count;
}

private static int factorial(int number) {
    if (number <= 1) {
        return 1;
    }
    return number * factorial(number - 1);
}

