public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;

    int totalElements = rows * cols;
    int[] result = new int[totalElements];
    int index = 0;

    // For each row
    for (int i = 0; i < rows; i++) {
        int r = i;
        int c = 0;

        while (r >= 0 && c < cols) {
            result[index++] = mat[r][c];
            r--;
            c++;
        }

        // Move to the next col if the row went off
        if (r < 0) {
            while (c < cols) {
                result[index++] = mat[0][c];
                c++;
            }
            break;
        }
    }

    // For each col
    for (int j = 1; j < cols; j++) {
        int r = rows - 1;
        int c = j;

        while (r >= 0 && c < cols) {
            result[index++] = mat[r][c];
            r--;
            c++;
        }

        // Move to the next col if the row went off
        if (c < cols) {
            while (r >= 0) {
                result[index++] = mat[r][cols - 1];
                r--;
            }
            break;
        }
    }

    return result;
}

