    }

    ArrayList<Integer> result = new ArrayList<>();
    int rowStart = 0;
    int colStart = 0;
    int rowCount = mat.length;
    int colCount = mat[0].length;
    int totalElements = rowCount * colCount;
    int dir = 0;  // 0 - right, 1 - down, 2 - left, 3 - up

    while (result.size() < totalElements) {
        if (dir == 0) {
            // Right Longest Diagonal
            while (rowStart < rowCount && colStart < colCount) {
                result.add(mat[rowStart][colStart]);
                rowStart++;
                colStart++;
            }

            // Other directions keep on incrementing the row or col
            if (colStart < colCount) {
                rowStart--;
            } else {
                colStart--;
                if (rowStart >= 0) {
                    dir = 1;
                }
            }
        } else if (dir == 1) {
            // Down Longest Diagonal
            while (rowStart < rowCount && colStart < colCount) {
                result.add(mat[rowStart][colStart]);
                rowStart++;
                colStart++;
            }

            // Other directions keep on incrementing the row or col
            if (rowStart < rowCount) {
                colStart--;
            } else {
                rowStart--;
                if (colStart >= 0) {
                    dir = 2;
                }
            }
        } else if (dir == 2) {
            // Left Longest Diagonal
            while (rowStart >= 0 && colStart < colCount) {
                result.add(mat[rowStart][colStart]);
                rowStart--;
                colStart++;
            }

            // Other directions keep on decrementing the row and col
            if (rowStart >= 0) {
                colStart--;
            } else {
                colStart--;
                if (colStart >= 0) {
                    dir = 3;
                }
            }
        } else if (dir == 3) {
            // Up Longest Diagonal
            while (rowStart >= 0 && colStart < colCount) {
                result.add(mat[rowStart][colStart]);
                rowStart--;
                colStart++;
            }

            // Other directions keep on decrementing the row and col
            if (colStart < colCount) {
                rowStart--;
            } else {
                rowStart--;
                if (rowStart >= 0) {
                    dir = 0;
                }
            }
        }
    }

    int[] res = new int[result.size()];
    for (int i = 0; i < res.length; i++) {
        res[i] = result.get(i);
    }
    return res;
}

