        while(row >= 0 && col < m) {
            result[k++] = mat[row][col];
            row--;
            col++;
        }
        row++;

        while(row < n && col >= 0) {
            result[k++] = mat[row][col];
            row++;
            col--;
        }
        col++;
    }

    return result;
}

public static int findSmallestInteger(int n) {
    int digits[] = new int[10];
    int temp = n;

    // Count the occurrence of each digit in n
    while (temp > 0) {
        digits[temp % 10]++;
        temp /= 10;
    }

    for (int i = 0; i < 10; i++) {
        // If there is more than one occurrence of a digit, swap the digits
        for (int j = i + 1; j < 10; j++) {
            if (digits[j] > 0) {
                int tempDigit = digits[i];
                digits[i] = digits[j];
                digits[j] = tempDigit;

                // Reconstruct the smallest integer
                int result = 0;
                for (int k = 0; k < 10; k++) {
                    result = result * 10 + digits[k];
                }

                // Check if the result is greater than n and not equal to n
                if (result > n && result != n) {
                    return result;
                }

                // If the current digit is greater than the next digit, swap back and continue
                digits[i] = tempDigit;
                digits[j] = temp;
            }
        }
    }

    // If no solution is found, return -1
    return -1;
}

public static int findSmallestInteger(int n) {
    int[] digits = new int[10];
    int original = n;
    int length = String.valueOf(n).length();
    int index = length - 1;

    // Count the frequency of each digit
    while (n > 0) {
        digits[n % 10]++;
        n /= 10;
    }

    for (int i = 1; i < 10; i++) {
        if (digits[i] > 0) {
            // Place the smallest available digit in the first position
            while (digits[i] == 0) {
                index--;
            }
            digits[i]--;

            // Rearrange the remaining digits
            while (index >= 0) {
                int remainder = (n % (int)Math.pow(10, index));
                carry = remainder / (int)Math.pow(10, index - 1);
                carry %= 10;
                int remainder = (remainder % (int)Math.pow(10, index));
                remainder -= carry;
                result = remainder + (int)Math.pow(10, length - index - 1);
                n -= carry * Math.pow(10, index);
                index--;
            }

            // Place the original digit in the last position
            digits[digits[10] - 1]++;

            return result;
        }
    }

    return -1;
}

