    List<String> result = new ArrayList<>();
    String prefix1 = "", suffix1 = "";
    String prefix2 = "", suffix2 = ""; // Left and right half prefixes of symmetric numbers

    if (n == 0) return result; // No symmetric numbers for length 0

    // Generate the first prefix of symmetric numbers
    prefix1 = "0";
    prefix2 = "8";
    suffix1 = "#|";
    suffix2 = "#|";

    while (true) {
        String numberWithPrefix1 = prefix1 + suffix1 + prefix2 + suffix2;
        String numberWithPrefix2 = prefix2 + suffix1 + prefix1 + suffix2;

        if (checkSymmetryWithPrefix(numberWithPrefix1, n)) {
            result.add(numberWithPrefix1);
        }
        if (checkSymmetryWithPrefix(numberWithPrefix2, n)) {
            result.add(numberWithPrefix2);
        }

        if (n == suffix1.length()) break;

        // Move the prefix1 and suffix1 pointers
        if (prefix1.charAt(suffix1.length() - 1) == '0') {
            temporary = prefix1;
            prefix1 = prefix2; // Right -> Left
            suffix1 = temporary;
        } else {
            temporary = prefix1;
            prefix1 = suffix1; // Left -> Right
            suffix1 = temporary;
        }

        // Update the suffix2 pointer
        suffix2 = suffix1 + "#|";
    }

    doubleValidCenterSymmetricNumbers(result, n);
}

