        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j * j <= i; ++j) {
                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            }
        }

        return dp[n];
    }

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    Arrays.fill(dp, n);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int square = i * i;
        for (int j = square; j <= n; j++) {
            dp[j] = Math.min(dp[j], dp[j - square] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    Arrays.fill(dp, n + 1); // Initialize the array with a large value

    dp[0] = 0; // Base case

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    return dp[n];
}

public static String reverseWords(String s) {
    char[] chars = s.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        int a = i;
        int b = i;
        while (b < chars.length - 1 && chars[b] != ' ') b++;
        while (a < b) {
            char temp = chars[a];
            chars[a] = chars[b];
            chars[b] = temp;
            a++;
            b--;
        }
    }
    return new String(chars);
}

public static String reverseWords(String sentence) {
        StringBuilder reversedSentence = new StringBuilder();

        for (String word : sentence.split(" ")) {
            StringBuilder reversedWord = new StringBuilder();
            for (int i = word.length() - 1; i >= 0; i--) {
                reversedWord.append(word.charAt(i));
            }
            reversedSentence.append(reversedWord.toString());
            reversedSentence.append(" ");
        }

        // Trim the last space and return the result
        return reversedSentence.toString().replaceAll("( )+", " ").trim();
    }

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        reversedSentence.append(new StringBuilder(word).reverse()).append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}

public static String reverseWords(String s) {
    StringBuilder reversedText = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ' ') {
            if (!currentWord.isEmpty()) {
                reversedText.append(reverseString(currentWord.toString()));
            }
            reversedText.append(' ');
            currentWord.setLength(0);
        } else {
            currentWord.append(s.charAt(i));
        }
    }

    if (!currentWord.isEmpty()) {
        reversedText.append(reverseString(currentWord.toString()));
    }

    return reversedText.toString();
}

private static String reverseString(String input) {
    StringBuilder reversedText = new StringBuilder();
    for (int i = input.length() - 1; i >= 0; i--) {
        reversedText.append(input.charAt(i));
    }
    return reversedText.toString();
}

